/// One Zacess theme: the interface and terminal colours a scene can draw with.
#[derive(Debug)]
pub struct ThemeData {
    /// The id the palette and the theme switcher use, such as `deep-contrast-dark`.
    pub id: &'static str,
    /// The full name, such as `Zacess Deep Contrast Dark`.
    pub name: &'static str,
    /// True for a dark background.
    pub dark: bool,
    pub background: Rgb,
    pub foreground: Rgb,
    pub muted: Rgb,
    pub accent: Rgb,
    pub link: Rgb,
    pub cursor: Rgb,
    pub error: Rgb,
    pub warning: Rgb,
    pub info: Rgb,
    /// Syntax colours in the order keyword, control, function, type, string, number, comment,
    /// property and regex.
    pub syntax: [Rgb; 9],
    /// The sixteen terminal colours in ANSI order.
    pub ansi: [Rgb; 16],
}

